def solve(inputs: dict) -> float:
    terms = inputs['terms']

    # Initialize p_prev and p_curr for the continued fraction convergents
    # p_{-1} = 1, p_0 = a_0
    p_prev = 1
    p_curr = terms[0]

    # Apply the recurrence p_n = a_n * p_{n-1} + p_{n-2}
    for i in range(1, len(terms)):
        p_next = terms[i] * p_curr + p_prev
        p_prev = p_curr
        p_curr = p_next

    return float(p_curr)

